package vn.smartfarm.iot.irrigation;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import vn.smartfarm.iot.nodes.WaterTelemetry;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.control.enabled=false","smartfarm.irrigation.demo-enabled=false","smartfarm.irrigation.monitor-enabled=true","smartfarm.irrigation-queue.scheduling-enabled=false"})
@EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class CircuitValveMonitorTest {
 @Autowired CircuitValveMonitor monitor;@Autowired IrrigationCircuits circuits;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired WaterTelemetry json;
 Instant at;long pumps,runs,valves,queued;String legacy;
 final UUID boot=UUID.fromString("71000000-0000-4000-8000-000000000001");
 @BeforeEach void setup(){clean();jdbc.update("INSERT INTO irrigation_demo_binding(singleton) VALUES(1) ON CONFLICT DO NOTHING");
  jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('MWATER','Water','AREA001','WATER',2)");jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES('MWATER','LOW','WATER_PRESENT','boolean'),('MWATER','FLOW','FLOW_RATE','L/min')");
  for(int i=1;i<=2;i++){jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES(?,'Soil','AREA001','SOIL',2)","MSOIL"+i);for(int c=1;c<=3;c++)jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES(?,?,'SOIL_MOISTURE','%')","MSOIL"+i,"SOIL"+c);
   jdbc.update("INSERT INTO irrigation_zone(zone_id,name,area_id,soil_node_id,expected_source,dry_threshold,wet_threshold) VALUES(?,'Monitor zone','AREA001',?,'SIMULATOR',30,35)","MZONE"+i,"MSOIL"+i);
   circuits.create(config(i));}
  at=Instant.now().minusSeconds(1);pumps=count("pump_command");runs=count("watering_run");valves=count("irrigation_demo_command");queued=count("irrigation_queue_request");legacy=jdbc.queryForObject("SELECT COALESCE(json_agg(s)::text,'[]') FROM irrigation_demo_status s",String.class);
 }
 void clean(){jdbc.update("DELETE FROM irrigation_circuit WHERE circuit_id IN ('MCTEST1','MCTEST2')");jdbc.update("DELETE FROM irrigation_zone WHERE zone_id IN ('MZONE1','MZONE2')");jdbc.update("DELETE FROM iot_node WHERE node_id IN ('MSOIL1','MSOIL2','MWATER')");}
 @AfterEach void unchanged(){try{assertEquals(pumps,count("pump_command"));assertEquals(runs,count("watering_run"));assertEquals(valves,count("irrigation_demo_command"));assertEquals(queued,count("irrigation_queue_request"));assertEquals(legacy,jdbc.queryForObject("SELECT COALESCE(json_agg(s)::text,'[]') FROM irrigation_demo_status s",String.class));}finally{clean();}}
 long count(String table){return jdbc.queryForObject("SELECT COUNT(*) FROM "+table,Long.class);}
 ObjectNode config(int i){return mapper.createObjectNode().put("circuitId","MCTEST"+i).put("name","Monitor "+i).put("zoneId","MZONE"+i).put("zoneRevision",1).put("controllerId","IRRIGATION0"+(i+1)).put("valveId","VALVE0"+(i+1)).put("pumpId","PUMP01").put("waterNodeId","MWATER").put("lowChannelId","LOW").put("flowChannelId","FLOW").put("expectedSource","SIMULATOR");}
 ObjectNode packet(int i,int seq){var p=mapper.createObjectNode().put("schemaVersion",1).put("controllerId","IRRIGATION0"+(i+1)).put("actuatorId","VALVE0"+(i+1)).put("circuitId","MCTEST"+i).put("circuitRevision",1).put("zoneId","MZONE"+i).put("zoneRevision",1).put("bootId",boot.toString()).put("sequence",seq).put("timestamp",at.plusMillis(seq).toString()).put("dataSource","SIMULATOR").put("monitorOnly",true).put("demoEnabled",false).put("gpioState","CLOSED").put("reason","BOOT").put("lastOrdinal",0).put("feedbackState","CLOSED");p.putObject("positionFeedback").put("version",1).put("enabled",true).put("state","CLOSED").putNull("fault");return p;}
 void receive(int i,ObjectNode p)throws Exception{monitor.receive("smartfarm/FARM001/VALVE0"+(i+1)+"/status",mapper.writeValueAsBytes(p),false);}
 IrrigationCircuits.View view(int i){return circuits.snapshot().circuits().stream().filter(c->c.config().circuitId().equals("MCTEST"+i)).findFirst().orElseThrow();}
 @Test void twoValvesAreIsolatedAndNeverBorrowLegacyStatus()throws Exception{receive(1,packet(1,1));assertEquals("CLOSED",view(1).valveState());assertEquals("NOT_CONNECTED",view(2).valveState());receive(2,packet(2,1));assertEquals("VALVE03",view(2).valveObservation().actuatorId());assertEquals(1,monitor.latest("VALVE02").sequence());assertFalse(circuits.snapshot().dispatchAvailable());assertTrue(circuits.snapshot().valveMonitorEnabled());}
 @Test void disabledProfileAndRetainedOversizedOrLegacyTopicsReject()throws Exception{var off=new CircuitValveMonitor(jdbc,json,false);byte[] p=mapper.writeValueAsBytes(packet(1,1));assertThrows(IllegalArgumentException.class,()->off.receive("smartfarm/FARM001/VALVE02/status",p,false));assertTrue(off.topics().isEmpty());assertThrows(IllegalArgumentException.class,()->monitor.receive("smartfarm/FARM001/VALVE02/status",p,true));assertThrows(IllegalArgumentException.class,()->monitor.receive("smartfarm/FARM001/VALVE01/status",p,false));assertThrows(IllegalArgumentException.class,()->monitor.receive("smartfarm/FARM001/VALVE02/ack",p,false));assertThrows(IllegalArgumentException.class,()->monitor.receive("smartfarm/FARM001/VALVE02/status",new byte[4097],false));assertNull(monitor.latest("VALVE02"));}
 @Test void unknownWrongControllerZoneAndRevisionNeverPersist()throws Exception{for(var p:List.of(packet(1,1).put("controllerId","IRRIGATION03"),packet(1,1).put("actuatorId","VALVE03"),packet(1,1).put("zoneId","MZONE2"),packet(1,1).put("zoneRevision",2),packet(1,1).put("circuitRevision",2),packet(1,1).put("circuitId","MCTEST2")))assertThrows(IllegalArgumentException.class,()->receive(1,p));assertEquals(0,count("circuit_valve_status"));}
 @Test void controlledOrPhysicalPacketsCannotEnterReadOnlyMonitor(){for(var p:List.of(packet(1,1).put("gpioState","OPEN"),packet(1,1).put("demoEnabled",true),packet(1,1).put("monitorOnly",false),packet(1,1).put("dataSource","PHYSICAL"),packet(1,1).put("lastOrdinal",1),packet(1,1).put("reason","COMMAND_OPEN")))assertThrows(IllegalArgumentException.class,()->receive(1,p));}
 @Test void staleFutureMalformedAndExtraFieldsReject()throws Exception{for(var p:List.of(packet(1,1).put("timestamp",Instant.now().minusSeconds(16).toString()),packet(1,1).put("timestamp",Instant.now().plusSeconds(10).toString()),packet(1,1).put("sequence",-1),packet(1,1).put("extra",true),packet(1,1).put("monitorOnly","true")))assertThrows(IllegalArgumentException.class,()->receive(1,p));String text=packet(1,1).toString();assertThrows(IllegalArgumentException.class,()->monitor.receive("smartfarm/FARM001/VALVE02/status",(text+"{}").getBytes(),false));assertThrows(IllegalArgumentException.class,()->monitor.receive("smartfarm/FARM001/VALVE02/status",("{\"schemaVersion\":1,"+text.substring(1)).getBytes(),false));}
 @Test void duplicatesAndRegressedTimeDoNotRefreshReceipt()throws Exception{receive(1,packet(1,2));var old=monitor.latest("VALVE02");receive(1,packet(1,2));receive(1,packet(1,1));receive(1,packet(1,3).put("timestamp",at.toString()));assertEquals(old,monitor.latest("VALVE02"));}
 @Test void newBootRetiresPreviousBootPermanently()throws Exception{receive(1,packet(1,1));UUID next=UUID.randomUUID();receive(1,packet(1,2).put("bootId",next.toString()));assertEquals(next,monitor.latest("VALVE02").bootId());receive(1,packet(1,100));assertEquals(next,monitor.latest("VALVE02").bootId());assertTrue(jdbc.queryForObject("SELECT retired FROM circuit_valve_boot WHERE valve_id='VALVE02' AND boot_id=?",Boolean.class,boot));}
 @Test void newBootWithOlderObservationCannotReplaceCurrent()throws Exception{receive(1,packet(1,10));receive(1,packet(1,1).put("bootId",UUID.randomUUID().toString()));assertEquals(boot,monitor.latest("VALVE02").bootId());}
 @Test void faultAndFeedbackCapabilityCannotDisappearInSameBoot()throws Exception{var p=packet(1,1).put("reason","POSITION_FAULT").put("feedbackState","CONFLICT");((ObjectNode)p.get("positionFeedback")).put("state","CONFLICT").put("fault","SWITCH_CONFLICT");receive(1,p);receive(1,packet(1,2));assertEquals("SWITCH_CONFLICT",monitor.latest("VALVE02").positionFeedback().fault());receive(1,packet(1,3).put("bootId",UUID.randomUUID().toString()));assertNull(monitor.latest("VALVE02").positionFeedback().fault());var noFeedback=packet(1,4).put("feedbackState","UNKNOWN").put("bootId",monitor.latest("VALVE02").bootId().toString());noFeedback.remove("positionFeedback");receive(1,noFeedback);assertNotNull(monitor.latest("VALVE02").positionFeedback());}
 @Test void legacyGpioNeverInventsPosition()throws Exception{var p=packet(1,1).put("feedbackState","UNKNOWN");p.remove("positionFeedback");receive(1,p);assertEquals("UNVERIFIED",view(1).valveState());assertNull(view(1).valveObservation().positionFeedback());}
 @Test void deviceFaultIsNotHiddenByClosedPosition()throws Exception{receive(1,packet(1,1).put("reason","DEVICE_FAULT"));assertEquals("FAULT",view(1).valveState());assertTrue(view(1).valveObservation().positionFeedback().closed());}
 @Test void staleAndDisabledObservationsRemainStoredButNotCurrent()throws Exception{receive(1,packet(1,1));var c=circuits.find("MCTEST1");var s=monitor.latest("VALVE02");assertEquals("STALE",monitor.state(c,s,Instant.now().plusSeconds(16)));assertEquals("MONITOR_DISABLED",new CircuitValveMonitor(jdbc,json,false).state(c,s,Instant.now()));assertEquals(s,monitor.latest("VALVE02"));}
 @Test void editingMappingRequiresNewBootAndMatchingRevision()throws Exception{receive(1,packet(1,1));circuits.update("MCTEST1",((ObjectNode)mapper.valueToTree(circuits.find("MCTEST1"))).put("name","New mapping"));assertEquals("CONFIG_CHANGED",view(1).valveState());assertThrows(IllegalArgumentException.class,()->receive(1,packet(1,2)));receive(1,packet(1,2).put("circuitRevision",2));assertEquals(1,monitor.latest("VALVE02").circuitRevision());receive(1,packet(1,3).put("circuitRevision",2).put("bootId",UUID.randomUUID().toString()));assertEquals("CLOSED",view(1).valveState());}
 @Test void changedZoneMarksObservationUnusableAndRejectsUpdates()throws Exception{receive(1,packet(1,1));jdbc.update("UPDATE irrigation_zone SET revision=2 WHERE zone_id='MZONE1'");assertEquals("CONFIG_CHANGED",view(1).valveState());assertThrows(IllegalArgumentException.class,()->receive(1,packet(1,2)));}
 @Test void topicsAreExactCurrentAndNeverContainCommandsOrLegacy(){var topics=monitor.topics();assertEquals(List.of("smartfarm/FARM001/VALVE02/status","smartfarm/FARM001/VALVE03/status"),topics);jdbc.update("UPDATE irrigation_zone SET revision=2 WHERE zone_id='MZONE1'");assertEquals(List.of("smartfarm/FARM001/VALVE03/status"),monitor.topics());}
 @Test void concurrentReorderedMessagesKeepHighestSequence()throws Exception{try(var pool=Executors.newFixedThreadPool(4)){var futures=new ArrayList<Future<?>>();for(int seq:List.of(9,1,5,3,10,6))futures.add(pool.submit(()->{try{receive(1,packet(1,seq));}catch(Exception e){throw new RuntimeException(e);}}));for(var f:futures)f.get(5,TimeUnit.SECONDS);}assertEquals(10,monitor.latest("VALVE02").sequence());}
 @Test void nativeMonitorEncoderMatchesRealReceiveContract()throws Exception{try(var in=getClass().getResourceAsStream("/circuit-valve-monitor-status.json")){assertNotNull(in);var p=(ObjectNode)mapper.readTree(in);p.put("circuitId","MCTEST1").put("zoneId","MZONE1").put("timestamp",Instant.now().toString());receive(1,p);assertEquals("CLOSED",view(1).valveState());assertTrue(view(1).valveObservation().monitorOnly());assertEquals("CLOSED",view(1).valveObservation().gpioState());}}
}
